INSERT INTO articles (id, title, source_name, publish_date, section, full_text, text_chunks, status, created_by) VALUES
  (1, 'Circle Line Is Finally Complete', 'The Straits Times', '2026-07-21', 'Newsroom', 'Three new MRT stations - Keppel, Cantonment and Prince Edward Road - opened on the Circle Line (CCL) on 12 July, finally closing the loop on a project that began 30 years ago in 2009. The first train arrived at Keppel at 6.14am. Among the commuters was 10-year-old Leroy Lim, a public transport enthusiast who travelled from Changi with his father to catch the first train, after his father promised to take him if he finished all his homework the night before. With the opening of the three stations, travel times for commuters are set to become shorter. The line now has a fleet of 87 trains, with over 70 used daily, and runs three services: clockwise, anti-clockwise, and one that runs to and from Dhoby Ghaut station. Local history has been built into the design of the new stations. Cantonment station sits beneath the former Tanjong Pagar Railway Station and pays tribute to the site with a curved ceiling, 24 murals and a large analogue clock. Keppel station is home to the first dedicated exhibition space in an MRT station, which currently houses a miniature model of the tunnel-boring machine used to dig the CCL extension. Over at Prince Edward Road station, the design reflects Singapore''s maritime heritage - passengers can spot a passenger service centre modelled after a wooden ship''s hull, as well as wave-like ceiling panels and shimmering artwork on the platforms.', '[{"chunk_id": "c1", "text": "Three new MRT stations - Keppel, Cantonment and Prince Edward Road - opened on the Circle Line (CCL) on 12 July, finally closing the loop on a project that began 30 years ago in 2009."}, {"chunk_id": "c2", "text": "The first train arrived at Keppel at 6.14am."}, {"chunk_id": "c3", "text": "Among the commuters was 10-year-old Leroy Lim, a public transport enthusiast who travelled from Changi with his father to catch the first train, after his father promised to take him if he finished all his homework the night before."}, {"chunk_id": "c4", "text": "With the opening of the three stations, travel times for commuters are set to become shorter."}, {"chunk_id": "c5", "text": "The line now has a fleet of 87 trains, with over 70 used daily, and runs three services: clockwise, anti-clockwise, and one that runs to and from Dhoby Ghaut station."}, {"chunk_id": "c6", "text": "Local history has been built into the design of the new stations."}, {"chunk_id": "c7", "text": "Cantonment station sits beneath the former Tanjong Pagar Railway Station and pays tribute to the site with a curved ceiling, 24 murals and a large analogue clock."}, {"chunk_id": "c8", "text": "Keppel station is home to the first dedicated exhibition space in an MRT station, which currently houses a miniature model of the tunnel-boring machine used to dig the CCL extension."}, {"chunk_id": "c9", "text": "Over at Prince Edward Road station, the design reflects Singapore''s maritime heritage - passengers can spot a passenger service centre modelled after a wooden ship''s hull, as well as wave-like ceiling panels and shimmering artwork on the platforms."}]', 'active', 2);
INSERT INTO articles (id, title, source_name, publish_date, section, full_text, text_chunks, status, created_by) VALUES
  (2, 'Spooks in the Hallways', 'The Straits Times', '2026-07-21', 'Deep Dive', 'Many castles, palaces and official residences have stood for hundreds of years, witnessing important moments in history - from celebrations to political unrest and war. With so many stories hidden within their walls, some of these places have become famous for their supposedly ghostly inhabitants. Japan''s prime minister''s official residence in Tokyo was built in 1929 and was the site of two attempted military coups in the 1930s, during which several people died. Since then, stories have spread that the spirits of those involved still roam the halls. Some people believe that prime ministers who live there do not remain in office for long, leading some leaders to choose to live elsewhere instead. The building was renovated in 2005, and a traditional Shinto cleansing ceremony was reportedly carried out before it reopened. Government officials say there is no evidence that the residence is haunted. Home to the Philippines'' leaders for generations, the palace was originally built in 1750 as a summer house before becoming home to Philippine presidents. Over the years, staff have shared tales of hearing footsteps and laughter in empty hallways, and of seeing mysterious figures vanish into thin air. Even President Ferdinand Marcos Jr has spoken about the palace''s ghostly reputation. The official home of Sweden''s royal family sits on an island near Stockholm and is a Unesco World Heritage Site. Unlike many spooky tales, these spirits are said to be friendly. Queen Silvia has said she believes she shares the palace with ''small friends'', describing the ghosts as ''all very friendly''. Local legends have even named some of the palace''s supposed spirits, including the mysterious ''Gray Man'' and ''White Lady''.', '[{"chunk_id": "c1", "text": "Many castles, palaces and official residences have stood for hundreds of years, witnessing important moments in history - from celebrations to political unrest and war."}, {"chunk_id": "c2", "text": "With so many stories hidden within their walls, some of these places have become famous for their supposedly ghostly inhabitants."}, {"chunk_id": "c3", "text": "Japan''s prime minister''s official residence in Tokyo was built in 1929 and was the site of two attempted military coups in the 1930s, during which several people died."}, {"chunk_id": "c4", "text": "Since then, stories have spread that the spirits of those involved still roam the halls."}, {"chunk_id": "c5", "text": "Some people believe that prime ministers who live there do not remain in office for long, leading some leaders to choose to live elsewhere instead."}, {"chunk_id": "c6", "text": "The building was renovated in 2005, and a traditional Shinto cleansing ceremony was reportedly carried out before it reopened."}, {"chunk_id": "c7", "text": "Government officials say there is no evidence that the residence is haunted."}, {"chunk_id": "c8", "text": "Home to the Philippines'' leaders for generations, the palace was originally built in 1750 as a summer house before becoming home to Philippine presidents."}, {"chunk_id": "c9", "text": "Over the years, staff have shared tales of hearing footsteps and laughter in empty hallways, and of seeing mysterious figures vanish into thin air."}, {"chunk_id": "c10", "text": "Even President Ferdinand Marcos Jr has spoken about the palace''s ghostly reputation."}, {"chunk_id": "c11", "text": "The official home of Sweden''s royal family sits on an island near Stockholm and is a Unesco World Heritage Site."}, {"chunk_id": "c12", "text": "Unlike many spooky tales, these spirits are said to be friendly."}, {"chunk_id": "c13", "text": "Queen Silvia has said she believes she shares the palace with ''small friends'', describing the ghosts as ''all very friendly''."}, {"chunk_id": "c14", "text": "Local legends have even named some of the palace''s supposed spirits, including the mysterious ''Gray Man'' and ''White Lady''."}]', 'active', 2);
INSERT INTO articles (id, title, source_name, publish_date, section, full_text, text_chunks, status, created_by) VALUES
  (3, 'Kids Turn Their Ideas Into Business Showcase', 'The Straits Times', '2026-07-21', 'Spotlight', 'During family holidays to Australia and London, eight-year-old Lee Rui Qi was captivated by 3D animal figurines but found their $20 to $40 price tag too expensive. This sparked an entrepreneurial idea: she got her father to buy a 3D printer, and launched a business selling her own collection of articulated, wiggly animal toys - including axolotls, whale sharks and snakes - priced at a modest $2 to $15. She took her creations to HarbourFront Centre on 11 and 12 July, joining 60 other resourceful children and teenagers showcasing their micro-businesses. The event was the second run of Singapore Kidpreneurs, a platform where young entrepreneurs aged four to 14 manage their own booths to sell items they have personally made or curated. Founder Jolene Ang said the programme gives young people the chance to build confidence and soft skills outside the classroom. Participants attended free workshops on financial literacy and basic business skills during the June school holidays. ''By pricing products, speaking to customers and experiencing the realities of selling, children begin to understand the value of money and the effort behind earning it,'' said Ang. Brothers Malcolm Ng, 11, and Magnus Ng, seven, spent three years developing a board game centred on restoring peace to five mythical realms. After their mother spotted a social media post about Singapore Kidpreneurs, they brought their creation to life, sourcing game pieces online and designing a glossy board. A basic game pack sells for $8. Cousins Kimberlyn Chia and 10-year-old Jadynn Lim curated ''blind bags'' designed to motivate and soothe children, after Jadynn noticed a schoolmate struggling with emotional outbursts. Their booth featured an interactive emotional check-in chart, and every customer received a free motivational sticker.', '[{"chunk_id": "c1", "text": "During family holidays to Australia and London, eight-year-old Lee Rui Qi was captivated by 3D animal figurines but found their $20 to $40 price tag too expensive."}, {"chunk_id": "c2", "text": "This sparked an entrepreneurial idea: she got her father to buy a 3D printer, and launched a business selling her own collection of articulated, wiggly animal toys - including axolotls, whale sharks and snakes - priced at a modest $2 to $15."}, {"chunk_id": "c3", "text": "She took her creations to HarbourFront Centre on 11 and 12 July, joining 60 other resourceful children and teenagers showcasing their micro-businesses."}, {"chunk_id": "c4", "text": "The event was the second run of Singapore Kidpreneurs, a platform where young entrepreneurs aged four to 14 manage their own booths to sell items they have personally made or curated."}, {"chunk_id": "c5", "text": "Founder Jolene Ang said the programme gives young people the chance to build confidence and soft skills outside the classroom."}, {"chunk_id": "c6", "text": "Participants attended free workshops on financial literacy and basic business skills during the June school holidays."}, {"chunk_id": "c7", "text": "''By pricing products, speaking to customers and experiencing the realities of selling, children begin to understand the value of money and the effort behind earning it,'' said Ang."}, {"chunk_id": "c8", "text": "Brothers Malcolm Ng, 11, and Magnus Ng, seven, spent three years developing a board game centred on restoring peace to five mythical realms."}, {"chunk_id": "c9", "text": "After their mother spotted a social media post about Singapore Kidpreneurs, they brought their creation to life, sourcing game pieces online and designing a glossy board."}, {"chunk_id": "c10", "text": "A basic game pack sells for $8."}, {"chunk_id": "c11", "text": "Cousins Kimberlyn Chia and 10-year-old Jadynn Lim curated ''blind bags'' designed to motivate and soothe children, after Jadynn noticed a schoolmate struggling with emotional outbursts."}, {"chunk_id": "c12", "text": "Their booth featured an interactive emotional check-in chart, and every customer received a free motivational sticker."}]', 'active', 2);
INSERT INTO tasks (id, article_id, type, payload) VALUES
  (1, 1, 'comprehension', '{"questions": [{"id": "q1", "question": "Which three MRT stations opened on the Circle Line?", "evidence_chunk_id": "c1", "options": ["Keppel, Cantonment and Prince Edward Road", "Keppel, Dhoby Ghaut and Tanjong Pagar", "Cantonment, Chinatown and Marina Bay", "Prince Edward Road, HarbourFront and Bishan"], "correct_index": 0}, {"id": "q2", "question": "How many years did the Circle Line project take to complete?", "evidence_chunk_id": "c1", "options": ["10 years", "20 years", "30 years", "50 years"], "correct_index": 2}, {"id": "q3", "question": "How many trains does the Circle Line now have in total?", "evidence_chunk_id": "c5", "options": ["70", "87", "100", "24"], "correct_index": 1}, {"id": "q4", "question": "What theme inspired the design of Prince Edward Road station?", "evidence_chunk_id": "c9", "options": ["Maritime heritage", "Railway history", "Space exploration", "Tropical rainforest"], "correct_index": 0}]}');
INSERT INTO tasks (id, article_id, type, payload) VALUES
  (2, 1, 'vocabulary', '{"questions": [{"id": "v1", "target_word": "enthusiast", "word_class": "noun", "context_sentence": "Among the commuters was 10-year-old Leroy Lim, a public transport enthusiast who travelled from Changi with his father to catch the first train.", "options": [{"text": "devotee", "role": "correct_synonym"}, {"text": "admirer", "role": "distant_synonym"}, {"text": "critic", "role": "antonym"}, {"text": "entomologist", "role": "lookalike"}], "correct_index": 0}]}');
INSERT INTO tasks (id, article_id, type, payload) VALUES
  (3, 1, 'reflect', '{"prompt": "If you could design the theme for a new MRT station, what theme would you choose and why? Think about how the Circle Line stations used history (Cantonment), exhibits (Keppel) and heritage (Prince Edward Road) as inspiration for their designs.", "model_answers": ["I would design a station themed around Singapore''s hawker culture, with tiled walls showing dishes like chicken rice and murals of hawker centres, because food is something everyone in Singapore can relate to and it would make commuting feel more like home.", "I''d choose a nature theme, with green walls and sounds of birds, because it would make the MRT feel calmer and remind commuters of Singapore''s parks even when they are underground.", "I would pick a space or technology theme with glowing lights and screens showing facts about Singapore''s future plans, because it would be exciting for children and show how the country keeps moving forward, just like the trains."]}');
INSERT INTO tasks (id, article_id, type, payload) VALUES
  (4, 2, 'comprehension', '{"questions": [{"id": "q1", "question": "Which historical event at Sori Kotei led to its ghost stories?", "evidence_chunk_id": "c3", "options": ["Two attempted military coups in the 1930s", "A fire that destroyed the building", "A royal wedding", "An earthquake"], "correct_index": 0}, {"id": "q2", "question": "According to Queen Silvia, what kind of ghosts live in Drottningholm Palace?", "evidence_chunk_id": "c13", "options": ["Frightening and dangerous", "Friendly, like ''small friends''", "Invisible and silent", "Angry former kings"], "correct_index": 1}, {"id": "q3", "question": "What did Malacanang Palace staff report experiencing?", "evidence_chunk_id": "c9", "options": ["Footsteps and laughter in empty hallways", "Loud music every night", "Objects flying across rooms", "Cold winds indoors"], "correct_index": 0}, {"id": "q4", "question": "In what year was Sori Kotei renovated, with a cleansing ceremony carried out?", "evidence_chunk_id": "c6", "options": ["1929", "1930", "1750", "2005"], "correct_index": 3}]}');
INSERT INTO tasks (id, article_id, type, payload) VALUES
  (5, 2, 'vocabulary', '{"questions": [{"id": "v1", "target_word": "urban legend", "word_class": "noun phrase", "context_sentence": "Over the years, an urban legend has grown around Sori Kotei, claiming the ghosts of former officials still walk its halls.", "options": [{"text": "folk tale", "role": "correct_synonym"}, {"text": "myth", "role": "distant_synonym"}, {"text": "documented fact", "role": "antonym"}, {"text": "urban planning", "role": "lookalike"}], "correct_index": 0}]}');
INSERT INTO tasks (id, article_id, type, payload) VALUES
  (6, 2, 'reflect', '{"prompt": "Compare the ghost stories from Sori Kotei and Malacanang Palace with those from Drottningholm Palace. How are they different in tone, and why do you think old buildings often become associated with ghost stories?", "model_answers": ["The stories about Sori Kotei and Malacanang Palace feel more serious and eerie because they are linked to real tragic events like coups and long histories of secrecy, while Drottningholm''s ghosts are described as playful and friendly, almost like a fun bedtime story. I think old buildings attract ghost stories because they have survived so many generations that people naturally wonder what memories might be left behind.", "I think the difference in tone comes from how each country''s culture views ghosts - some see them as something to fear, while Queen Silvia''s palace treats them almost like family. Old buildings become linked to ghost stories because they''re often quiet, dark and full of history that nobody living today witnessed, so people fill in the gaps with their imagination.", "The Japanese and Philippine stories are spookier because they come from unexplained tragedies, but the Swedish story is comforting because a real person, the Queen, chose to describe the ghosts warmly instead of scarily. I think grand old buildings become linked to hauntings because their creaky sounds and dim lighting naturally make people feel like something unseen is nearby."]}');
INSERT INTO tasks (id, article_id, type, payload) VALUES
  (7, 3, 'comprehension', '{"questions": [{"id": "q1", "question": "What did Lee Rui Qi make and sell at her stall?", "evidence_chunk_id": "c2", "options": ["3D-printed wiggly animal toys", "Hand-painted greeting cards", "Baked cookies", "Bracelets and badges"], "correct_index": 0}, {"id": "q2", "question": "What age range can join Singapore Kidpreneurs?", "evidence_chunk_id": "c4", "options": ["4 to 14", "8 to 18", "10 to 16", "6 to 12"], "correct_index": 0}, {"id": "q3", "question": "How long did it take Malcolm and Magnus Ng to develop their board game?", "evidence_chunk_id": "c8", "options": ["One year", "Three years", "Five years", "Six months"], "correct_index": 1}, {"id": "q4", "question": "Why did Jadynn Lim decide to create ''blind bags''?", "evidence_chunk_id": "c11", "options": ["To help a schoolmate who was struggling with emotional outbursts", "To raise money for a school trip", "To sell leftover toys", "Because her teacher assigned it as homework"], "correct_index": 0}]}');
INSERT INTO tasks (id, article_id, type, payload) VALUES
  (8, 3, 'vocabulary', '{"questions": [{"id": "v1", "target_word": "entrepreneur", "word_class": "noun", "context_sentence": "The event was the second run of Singapore Kidpreneurs, a platform where young entrepreneurs aged four to 14 manage their own booths to sell items they have personally made or curated.", "options": [{"text": "business owner", "role": "correct_synonym"}, {"text": "investor", "role": "distant_synonym"}, {"text": "customer", "role": "antonym"}, {"text": "entrant", "role": "lookalike"}], "correct_index": 0}]}');
INSERT INTO tasks (id, article_id, type, payload) VALUES
  (9, 3, 'reflect', '{"prompt": "Why do you think it is important for children to learn about money and running a business at a young age? Think about what Malcolm, Magnus and Jadynn''s businesses show about character as well as money skills.", "model_answers": ["I think learning about money early helps children understand that things cost effort, not just cash - like how Malcolm and Magnus spent three years building their game instead of expecting it to sell instantly. It also builds patience and problem-solving skills that help in many areas of life, not just business.", "Businesses like Jadynn''s blind bags show that entrepreneurship isn''t only about earning money - it can also be about noticing a problem, like a friend''s feelings, and finding a caring way to help. Learning this young could make children more thoughtful adults who think about others, not just profit.", "I believe starting young lets children make small mistakes, like pricing something wrong, while the stakes are still low, so they can learn important lessons safely. It also gives them confidence to speak to strangers and manage their own project, which is a skill that helps far beyond running a stall."]}');
